-- CalorieScience Companion — adherence workflow schema
-- Run once in Supabase → SQL Editor. Safe to re-run (idempotent).
-- Demo data itself is generated by the app (src/lib/seed.ts) relative to "today",
-- so the 7-day history never goes stale. Use "Reset demo" in the app to re-seed.

-- ───────────────────────────── Tables ─────────────────────────────

create table if not exists clients (
  id               text primary key,
  name             text not null,
  age              int,
  occupation       text,
  goal             text,
  programme_start  date not null,
  programme_weeks  int  not null default 4,
  needs_follow_up  boolean not null default false,
  follow_up_reason text,
  last_reviewed_at timestamptz,
  plan_review_status text not null default 'none'
    check (plan_review_status in ('none', 'in_review')),
  created_at       timestamptz not null default now()
);

-- What the practitioner PLANNED. Never mutated by client behaviour.
create table if not exists meal_plan_items (
  id           text primary key,
  client_id    text not null references clients(id) on delete cascade,
  meal_type    text not null check (meal_type in ('breakfast','lunch','snack','dinner')),
  label        text not null,
  planned_time time not null,
  title        text not null,
  description  text,
  sort_order   int  not null default 0
);

-- What the client ACTUALLY did. One row per (client, planned meal, day).
-- Absence of a row = "not logged" (missing data), which is NOT the same as "skipped".
create table if not exists meal_logs (
  id              text primary key default gen_random_uuid()::text,
  client_id       text not null references clients(id) on delete cascade,
  plan_item_id    text not null references meal_plan_items(id) on delete cascade,
  log_date        date not null,
  status          text not null check (status in ('followed','partial','substituted','skipped')),
  substitute_text text,
  reason          text check (reason in ('no_time','at_work','not_hungry','unavailable','forgot','social','other')),
  hunger          int  check (hunger between 1 and 5),   -- 1 still very hungry … 3 satisfied … 5 overly full
  prep_difficulty text check (prep_difficulty in ('easy','ok','hard')),
  actual_time     time,
  comment         text,
  logged_at       timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  unique (client_id, plan_item_id, log_date)
);
create index if not exists meal_logs_client_date on meal_logs (client_id, log_date);

-- Issues raised by the client ("I can't manage my afternoon snack at the office").
create table if not exists client_feedback (
  id           text primary key default gen_random_uuid()::text,
  client_id    text not null references clients(id) on delete cascade,
  plan_item_id text references meal_plan_items(id) on delete set null,
  category     text not null check (category in ('timing','preparation','hunger','availability','other')),
  message      text not null,
  status       text not null default 'open' check (status in ('open','acknowledged','resolved')),
  created_at   timestamptz not null default now()
);

-- Everything the practitioner does: an append-only audit trail.
create table if not exists practitioner_actions (
  id                text primary key default gen_random_uuid()::text,
  client_id         text not null references clients(id) on delete cascade,
  type              text not null check (type in ('note','flag','unflag','recommendation','reviewed','plan_review')),
  body              text,
  plan_item_id      text references meal_plan_items(id) on delete set null,
  feedback_id       text references client_feedback(id) on delete set null,
  visible_to_client boolean not null default false,
  client_seen_at    timestamptz,
  author            text not null default 'Dr. Meera Iyer',
  created_at        timestamptz not null default now()
);
create index if not exists actions_client on practitioner_actions (client_id, created_at desc);

-- ───────────────────────────── Security ─────────────────────────────
-- PROTOTYPE ONLY: there is no auth, so the anon/publishable key may read & write
-- the demo tables. In production these become per-role policies keyed on
-- auth.uid() (client sees own rows; practitioner sees rows of assigned clients).

alter table clients              enable row level security;
alter table meal_plan_items      enable row level security;
alter table meal_logs            enable row level security;
alter table client_feedback      enable row level security;
alter table practitioner_actions enable row level security;

do $$
declare t text;
begin
  foreach t in array array['clients','meal_plan_items','meal_logs','client_feedback','practitioner_actions'] loop
    execute format('drop policy if exists demo_all on %I', t);
    execute format('create policy demo_all on %I for all to anon, authenticated using (true) with check (true)', t);
  end loop;
end $$;

-- ───────────────────────────── Realtime ─────────────────────────────
-- Lets the practitioner dashboard and the client app update live.

do $$
declare t text;
begin
  foreach t in array array['clients','meal_logs','client_feedback','practitioner_actions'] loop
    if not exists (
      select 1 from pg_publication_tables
      where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t
    ) then
      execute format('alter publication supabase_realtime add table %I', t);
    end if;
  end loop;
end $$;
